const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.spark}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=id=>PLACES.find(p=>p.id===id);
function readStore(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}}
function putStore(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('Your browser could not save this. It will last for this visit only.');return false}}
let savedRaw=readStore('cityside-saved',[]),saved=new Set(Array.isArray(savedRaw)?savedRaw.filter(id=>byId(id)):[]);
let mode=readStore('cityside-mode','visitor')==='local'?'local':'visitor',filter='All places',query='',locationPoint=null;
let progress=readStore('cityside-progress',{});if(!progress||Array.isArray(progress)||typeof progress!=='object')progress={};
for(const w of WALKS)progress[w.id]=Array.isArray(progress[w.id])?progress[w.id].filter(id=>w.stops.includes(id)):[];
let userMarker=null,mapInstance=null,toastTimer,previousPage='explore',activeWalk=null;
const main=document.getElementById('main');
const themeIcon=t=>({'Film & TV':'film','Books':'book','Hidden gems':'spark','Architecture':'building'}[t]||'compass');
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500)}
function distance(p){return locationPoint?LookUpRoutes.miles(locationPoint,p):null}
function distanceLabel(p,long){const d=distance(p);if(d===null)return long?'':`${p.time} min stop`;return LookUpRoutes.distanceText(d)+(long?` · about ${LookUpRoutes.walkMinutes(d)} min walk`:'')}
function distanceSpan(p,long){return `<span data-distance="${p.id}"${long?' data-long':''}>${distanceLabel(p,long)}</span>`}
function saveButton(p){return `<button class="save-button ${saved.has(p.id)?'saved':''}" data-action="save" data-id="${p.id}" aria-pressed="${saved.has(p.id)}" aria-label="${saved.has(p.id)?'Unsave':'Save'} ${esc(p.name)}">${icon('bookmark')}</button>`}
function placeCard(p){const tag=filter!=='All places'&&p.tags.includes(filter)?filter:p.tags[0];return `<article class="place-card">${saveButton(p)}<a href="#place/${p.id}" aria-label="Explore ${esc(p.name)}"><div class="card-image"><img src="assets/${p.id}.webp" alt="${esc(p.name)}" loading="lazy"><span class="card-top-tag">${icon(themeIcon(tag))}${tag}</span></div><div class="card-meta"><span>${p.neighborhood}</span>${distanceSpan(p)}</div><h3>${p.name}</h3><p>${p.teaser}</p></a></article>`}
function walkFacts(w){return `<div class="walk-facts"><span>${icon('clock')}~${w.minutes} min</span><span>${icon('walk')}~${w.miles} mi</span><span>${w.stops.length} stops</span></div>`}
function walkCard(w){const start=byId(w.stops[0]);return `<a href="#route/${w.id}" class="walk-card"><img src="assets/${w.image}.webp" alt="${esc(byId(w.image).name)}" loading="lazy"><div class="walk-card-body"><span class="eyebrow">${w.area} · SELF-GUIDED WALK</span><h3>${w.title}</h3><p>${w.subtitle}</p>${walkFacts(w)}${locationPoint?`<p class="route-start">${icon('location')}Starts ${distanceSpan(start)}</p>`:''}<span class="walk-arrow">${icon('arrow')}</span></div></a>`}
function nav(active){const tabs=[['explore','compass','Explore'],['routes','walk','Routes'],['map','map','Map'],['saved','bookmark','Saved']];const html=tabs.map(([id,ic,label])=>`<a href="#${id}" class="nav-link ${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('');document.querySelector('.desktop-nav').innerHTML=html;document.querySelector('.bottom-nav').innerHTML=html}
function nearestPlace(){return locationPoint?PLACES.reduce((a,b)=>distance(b)<distance(a)?b:a):null}
function heroImage(){const n=nearestPlace();if(n)return `<a href="#place/${n.id}" class="hero-image" data-hero="${n.id}"><img src="assets/${n.id}.webp" alt="${esc(n.name)}" fetchpriority="high"><div class="hero-stamp"><span>Take a</span>${icon('walk')}<span>closer look</span></div><div class="hero-caption"><div><span class="eyebrow">CLOSEST TO YOU · ${distanceSpan(n)}</span><strong>${n.teaser}</strong><span class="caption-location">${n.name} · ${n.neighborhood}</span></div><span class="round-arrow">${icon('arrow')}</span></div></a>`;
 return `<a href="#place/${mode==='local'?'jefferson':'nypl'}" class="hero-image" data-hero=""><img src="assets/${mode==='local'?'jefferson':'nypl'}.webp" alt="${mode==='local'?'Jefferson Market Library at sunset':'New York Public Library on Fifth Avenue'}" fetchpriority="high"><div class="hero-stamp"><span>Take a</span>${icon('walk')}<span>closer look</span></div><div class="hero-caption"><div><span class="eyebrow">${mode==='local'?'A NEIGHBORHOOD SECOND CHAPTER':'YOU’VE SEEN IT ON SCREEN'}</span><strong>${mode==='local'?'A courthouse. Now your library.':'More than a movie moment.'}</strong><span class="caption-location">${mode==='local'?'Jefferson Market Library · Greenwich Village':'New York Public Library · Fifth Avenue'}</span></div><span class="round-arrow">${icon('arrow')}</span></div></a>`}
function renderExplore(){main.innerHTML=`<section class="hero"><div><span class="eyebrow">FOR THE CURIOUS. FOR EVERYONE.</span><h1>A familiar city.<br> <em>A fresh pair of eyes.</em></h1><p>Big landmarks. Little discoveries. Find the stories behind New York’s buildings, one walk at a time.</p><div class="segmented" aria-label="Choose your starting point"><button data-action="mode" data-mode="visitor" aria-pressed="${mode==='visitor'}" class="${mode==='visitor'?'active':''}">I’m visiting</button><button data-action="mode" data-mode="local" aria-pressed="${mode==='local'}" class="${mode==='local'?'active':''}">I live here</button></div></div><div id="hero-slot">${heroImage()}</div></section><section aria-label="Find landmarks"><div class="discover-controls"><label class="search-box">${icon('search')}<input id="search" type="search" value="${esc(query)}" placeholder="A place, a neighborhood, a story…" aria-label="Search places, neighborhoods, films, and books"></label><button class="near-button" data-action="near">${icon('location')}Near me</button></div><div class="filters" role="group" aria-label="Filter places">${['All places','Film & TV','Books','Hidden gems','Architecture'].map(t=>`<button class="chip ${filter===t?'active':''}" data-action="filter" data-filter="${esc(t)}" aria-pressed="${filter===t}">${icon(themeIcon(t))}${t}</button>`).join('')}</div><div class="section-heading"><div><h2>${mode==='local'?'A new side of your city':'Find your next story'}</h2><p>${mode==='local'?'Small discoveries, hiding in plain sight.':'A few favorites to get you wandering.'}</p></div><a href="#map" class="text-link">Explore the map ${icon('arrow')}</a></div><div id="place-results"></div></section><section class="walk-section"><div class="section-heading"><div><span class="eyebrow">GOOD STORIES. GOOD STROLLS.</span><h2>Take the scenic route.</h2></div><a class="text-link" href="#routes">All scenic routes ${icon('arrow')}</a></div><div class="walk-grid">${(mode==='local'?[WALKS[1],WALKS[0]]:WALKS).map(walkCard).join('')}</div></section><div class="callout">${icon('spark')}<p><strong>No architecture degree required.</strong>Just comfortable shoes and a little curiosity.</p></div>`;renderResults();document.getElementById('search').addEventListener('input',e=>{query=e.target.value;renderResults()})}
function renderResults(){let list=PLACES.filter(p=>(filter==='All places'||p.tags.includes(filter))&&[p.name,p.neighborhood,p.teaser,p.story,...p.culture.flatMap(c=>[c.title,c.text])].join(' ').toLowerCase().includes(query.toLowerCase().trim()));if(locationPoint)list.sort((a,b)=>distance(a)-distance(b));else{const order=mode==='local'?['jefferson','haughwout','puck','washington','grandcentral','flatiron','nypl','plaza']:['flatiron','nypl','plaza','grandcentral','puck','jefferson','washington','haughwout'];list.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id))}document.getElementById('place-results').innerHTML=`${query||filter!=='All places'||locationPoint?`<p class="result-status" role="status">${list.length} ${list.length===1?'place':'places'}${locationPoint?' · Nearest first, updating as you walk':''}</p>`:''}${list.length?`<div class="places-grid">${list.map(placeCard).join('')}</div>`:`<div class="empty-state">${icon('search')}<h2>A different kind of discovery?</h2><p>No matches in our first eight places. Try “SoHo,” “Eloise,” or another theme.</p><button class="button secondary" data-action="reset-filters">Show all places</button></div>`}`}
function credit(p){const c=CREDITS[p.id];return c?`<p>Photo: ${esc(c.author)} · <a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">${esc(c.license)} / original image</a>. Displayed with layout cropping.</p>`:''}
function directions(p,origin){return 'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(p.address+', New York, NY')+'&travelmode=walking'+(origin?'&origin='+encodeURIComponent(origin.address+', New York, NY'):'')}
function renderPlace(p){if(!p){renderNotFound();return}document.title=`${p.name} — LookUp NYC`;const walkContext=WALKS.find(w=>w.id===activeWalk&&w.stops.includes(p.id));main.innerHTML=`<a href="#${walkContext?'route/'+walkContext.id:previousPage}" class="back-link">${icon('back')}${walkContext?'Back to your route':'Back to '+(previousPage==='saved'?'saved places':previousPage==='map'?'map':previousPage==='routes'?'scenic routes':'explore')}</a><article><div class="detail-hero"><img src="assets/${p.id}.webp" alt="${esc(p.name)}">${saveButton(p)}<div class="detail-title"><span class="eyebrow">${p.neighborhood} · ${p.year}</span><h1>${p.name}</h1><p>${p.style}</p></div></div><div class="detail-body"><p class="place-distance" ${locationPoint?'':'hidden'}>${icon('location')}${distanceSpan(p,true)}</p><div class="detail-actions"><a class="button" href="${directions(p)}" target="_blank" rel="noopener noreferrer">${icon('walk')}Get directions</a><button class="button secondary" data-action="save" data-id="${p.id}" aria-pressed="${saved.has(p.id)}">${icon('bookmark')}${saved.has(p.id)?'Saved':'Save'}</button></div>${audioPanel(p)}<section class="story-section"><span class="eyebrow">THE SHORT STORY</span><h2>${p.hook}</h2><p>${p.story}</p></section><section class="story-section"><span class="eyebrow">WHILE YOU’RE HERE</span><h2>Three things to spot.</h2><ol class="look-list">${p.looks.map(l=>`<li>${l}</li>`).join('')}</ol></section><section class="story-section"><span class="eyebrow">THERE’S MORE TO THE STORY</span><h2>${p.culture.some(c=>c.type.startsWith('On '))?'You might know it from…':'A little closer to city life.'}</h2>${p.culture.map(c=>`<div class="culture-card"><span class="eyebrow">${c.type}</span><h3>${c.title}</h3><p>${c.text}</p></div>`).join('')}</section><div class="visit-note">${icon('info')}<div><strong>Before you go</strong><p>${p.tip}</p><p>${p.address} · Allow about ${p.time} minutes.</p></div></div><details><summary>Visitor links & story credits</summary><ul class="source-list">${p.sources.map(([title,url])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${title} ↗</a></li>`).join('')}</ul>${credit(p)}<p>Stories are short editorial summaries. Narration uses your device’s voice.</p></details>${WALKS.filter(w=>w.stops.includes(p.id)).map(w=>`<div class="callout">${icon('walk')}<div><span class="mini-label">MAKE A WALK OF IT</span><a href="#route/${w.id}"><strong>${w.title} →</strong></a><p>${w.stops.length} stops · About ${w.minutes} minutes</p></div></div>`).join('')}</div></article>`}
const ROUTE_FILTERS=[
 ['length','Length',[['any','Any length'],['short','Under 1 mi'],['medium','1–2 mi'],['long','Over 2 mi']]],
 ['time','Time',[['any','Any time'],['quick','Under 45 min'],['hour','About an hour'],['long','Over 75 min']]],
 ['region','Area',[['All','All areas'],['Midtown','Midtown'],['Downtown','Downtown']]],
 ['theme','Theme',[['All','All themes'],...[...new Set(WALKS.flatMap(w=>w.tags))].map(t=>[t,t])]],
 ['sort','Sort',[['recommended','Recommended'],['nearest','Nearest start'],['shortest','Shortest first'],['longest','Longest first']]]];
let routeFilters={length:'any',time:'any',region:'All',theme:'All',sort:'recommended'};
function renderRouteResults(){const el=document.getElementById('route-results');if(!el)return;const list=LookUpRoutes.filterRoutes(WALKS,routeFilters,byId,locationPoint),active=Object.entries(routeFilters).some(([k,v])=>k!=='sort'&&!['any','All'].includes(v));el.innerHTML=`<p class="result-status" role="status">${list.length} ${list.length===1?'route':'routes'}${routeFilters.sort==='nearest'&&locationPoint?' · Nearest start first':''}${active?' · <button class="text-link inline" data-action="clear-route-filters">Clear filters</button>':''}</p>${list.length?`<div class="walk-grid">${list.map(walkCard).join('')}</div>`:`<div class="empty-state">${icon('walk')}<h2>No route fits just yet.</h2><p>Try a different length or area. New routes are on the way.</p><button class="button secondary" data-action="clear-route-filters">Show all routes</button></div>`}`}
function renderWalks(){document.title='Scenic routes — LookUp NYC';main.innerHTML=`<div class="page-top"><span class="eyebrow">ONE STEP. ANOTHER STORY.</span><h1>Scenic routes.</h1><p>Self-guided walks between the city’s great buildings, made for your own pace. Filter by time, length, or what you love.</p></div><div class="route-filters" role="group" aria-label="Filter routes">${ROUTE_FILTERS.map(([key,label,opts])=>`<label class="route-filter"><span>${label}</span><select data-route-filter="${key}">${opts.map(([v,t])=>`<option value="${esc(v)}" ${routeFilters[key]===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`).join('')}<button class="near-button" data-action="near">${icon('location')}Near me</button></div><div id="route-results"></div><div class="callout">${icon('walk')}<p><strong>Walk a little. Stop a little.</strong>Times include walking and short story stops. Add time for cafés, indoor visits, and your own detours.</p></div>`;renderRouteResults();setLiveButtons()}
function renderWalk(w){if(!w){renderNotFound();return}document.title=`${w.title} — LookUp NYC`;const done=progress[w.id]||[],next=w.stops.find(id=>!done.includes(id));main.innerHTML=`<a href="#routes" class="back-link">${icon('back')}All scenic routes</a><section class="walk-heading"><div><span class="eyebrow">${w.area} · SELF-GUIDED WALK</span><h1>${w.title}</h1><p>${w.description}</p>${walkFacts(w)}<p class="route-start" ${locationPoint?'':'hidden'}>${icon('location')}Start: ${byId(w.stops[0]).name}, ${distanceSpan(byId(w.stops[0]),true)}</p><button class="button orange" data-action="start-walk" data-id="${w.id}">${icon('walk')}${done.length?'Continue your walk':'Start this walk'}</button></div><img src="assets/${w.image}.webp" alt="${esc(byId(w.image).name)}"></section><div class="progress-box" id="walk-progress"><div class="progress-text"><strong>${done.length===w.stops.length?'A little more New York, discovered.':'Your little adventure'}</strong><span>${done.length} of ${w.stops.length} stops visited</span></div><div class="progress-track" role="progressbar" aria-valuenow="${done.length}" aria-valuemin="0" aria-valuemax="${w.stops.length}" aria-label="Walk completion"><span style="width:${done.length/w.stops.length*100}%"></span></div><p>${next?'Up next: '+byId(next).name:'You’ve visited every stop. Your progress is saved on this device.'}</p></div><div class="walk-overview"><section><div class="section-heading"><h2>Your stops</h2><span class="mini-label">A route to make your own</span></div><div class="route-stops">${w.stops.map((id,i)=>{const p=byId(id),complete=done.includes(id);return `<div class="route-stop ${complete?'complete':''}" id="stop-${id}"><span class="stop-number">${complete?icon('check'):i+1}</span><div class="stop-body"><a href="#place/${id}">${p.name}</a><p>${w.legs[i]}</p><div class="stop-actions"><a href="#place/${id}">Read the story</a><button data-audio="tour-listen" data-place="${id}">Listen</button><a href="${directions(p,i?byId(w.stops[i-1]):null)}" target="_blank" rel="noopener noreferrer">Directions ↗</a><button data-action="visited" data-walk="${w.id}" data-id="${id}" aria-pressed="${complete}" class="${complete?'active':''}">${complete?'✓ Visited':'Mark visited'}</button></div></div></div>`}).join('')}</div><div class="walk-controls">${next?`<a class="button" href="#place/${next}">Next story ${icon('arrow')}</a>`:''}<a class="button secondary" href="${LookUpRoutes.mapsLink(w,byId)}" target="_blank" rel="noopener noreferrer">${icon('map')}Full route in Maps ↗</a>${done.length?`<button class="button secondary" data-action="reset-walk" data-id="${w.id}">Reset progress</button>`:''}</div></section><aside><div class="map-canvas walk-map" id="walk-map" aria-label="Map of walk stops"></div><p class="map-note">Simplified location overview. Dotted lines show stop order, not the street route. Open each stop’s walking directions to navigate.</p><div class="visit-note">${icon('info')}<p>Distances and times are approximate. Check crossings and current conditions as you go. Interior visits depend on access; the outdoor route does not require admission.</p></div></aside></div>`;initMap('walk-map',w.stops.map(byId),true)}
function renderSaved(){const places=PLACES.filter(p=>saved.has(p.id));main.innerHTML=`<div class="page-top"><span class="eyebrow">YOUR OWN NEW YORK</span><h1>Keep a little curiosity.</h1><p>Your saved places, ready for the next time you’re out. Saved on this device.</p></div>${places.length?`<div class="places-grid">${places.map(placeCard).join('')}</div>`:`<div class="empty-state">${icon('bookmark')}<h2>A few places worth keeping.</h2><p>Tap the bookmark on any landmark to start your own little collection.</p><a class="button" href="#explore">Find a place ${icon('arrow')}</a></div>`}`}
function mapList(){const list=[...PLACES];if(locationPoint)list.sort((a,b)=>distance(a)-distance(b));return list.map(p=>`<a class="map-place" href="#place/${p.id}"><img src="assets/${p.id}.webp" alt="" loading="lazy"><span><strong>${PLACES.indexOf(p)+1}. ${p.name}</strong><small>${p.neighborhood} · ${distanceSpan(p)}</small></span></a>`).join('')}
function renderMap(){main.innerHTML=`<div class="page-top"><span class="eyebrow">FOLLOW YOUR CURIOSITY</span><h1>There’s a story nearby.</h1><p>${PLACES.length} places to start. Tap a pin to meet the building.</p><button class="near-button" data-action="near">${icon('location')}Near me</button></div><div class="map-layout"><div id="places-map" class="map-canvas" aria-label="Interactive map of landmarks"></div><div class="map-list" id="map-list">${mapList()}</div></div><p class="map-note" id="map-status">Simplified location overview, not a street map. Pins show landmark locations. Open a building for street-by-street walking directions.</p>`;initMap('places-map',PLACES,false)}
function initMap(el,places,walk){
 const container=document.getElementById(el);
 if(!window.L){container.innerHTML='<div class="empty-state"><p>The overview could not load. Explore the landmark links and open walking directions.</p></div>';return}
 const map=L.map(el,{scrollWheelZoom:false,zoomControl:true,minZoom:11,maxZoom:17});mapInstance=map;
 map.attributionControl.setPrefix('<a href="https://leafletjs.com" target="_blank" rel="noopener noreferrer">Leaflet</a>');
 map.attributionControl.addAttribution('Cityside · schematic overview');
 const land=[[40.700,-74.019],[40.713,-74.016],[40.730,-74.012],[40.745,-74.008],[40.759,-74.001],[40.778,-73.988],[40.795,-73.974],[40.812,-73.956],[40.820,-73.933],[40.806,-73.928],[40.789,-73.938],[40.774,-73.943],[40.759,-73.958],[40.747,-73.969],[40.736,-73.973],[40.723,-73.973],[40.712,-73.978],[40.701,-73.997]];
 L.polygon(land,{color:'#a9bddf',weight:1,fillColor:'#eef1ff',fillOpacity:1,interactive:false}).addTo(map);
 L.polygon([[40.768,-73.981],[40.800,-73.958],[40.796,-73.949],[40.764,-73.973]],{color:'#8ad8cc',weight:1,fillColor:'#b0eadc',fillOpacity:1,interactive:false}).addTo(map);
 const labels=[['MIDTOWN',40.758,-73.988],['CHELSEA',40.746,-73.999],['GREENWICH VILLAGE',40.732,-74.008],['SOHO',40.724,-74.009],['CENTRAL PARK',40.776,-73.968]];
 labels.forEach(([name,lat,lng])=>L.marker([lat,lng],{interactive:false,keyboard:false,icon:L.divIcon({className:'area-label',html:esc(name),iconSize:[110,20],iconAnchor:[55,10]})}).addTo(map));
 if(walk)L.polyline(places.map(p=>[p.lat,p.lng]),{color:'#3452ed',weight:2,dashArray:'5 8',opacity:.7,interactive:false}).addTo(map);
 places.forEach((p,i)=>L.marker([p.lat,p.lng],{icon:L.divIcon({className:'map-marker'+(places.length>3?' small':''),html:String(i+1),iconSize:places.length>3?[26,26]:[34,34],iconAnchor:places.length>3?[13,13]:[17,17]}),title:p.name,alt:p.name}).addTo(map).bindPopup(`<strong>${esc(p.name)}</strong><br>${esc(p.neighborhood)}<a href="#place/${p.id}">Explore this place →</a>`));
 map.fitBounds(places.map(p=>[p.lat,p.lng]),{padding:[42,42],maxZoom:14});
 userMarker=null;if(locationPoint&&!walk)userMarker=L.circleMarker([locationPoint.lat,locationPoint.lng],{radius:8,color:'#fff',weight:3,fillColor:'#397bbb',fillOpacity:1}).addTo(map).bindPopup('You are here');
 setTimeout(()=>{if(mapInstance===map)map.invalidateSize()},50);
}
function renderNotFound(){main.innerHTML=`<div class="page-top"><h1>A little off the route.</h1><p>We couldn’t find that place or walk.</p><a class="button" href="#explore">Back to exploring</a></div>`}
function render(){if(mapInstance){mapInstance.remove();mapInstance=null}document.title='LookUp NYC';let [page,id]=(location.hash.slice(1)||'explore').split('/');if(page==='walks'){history.replaceState(null,'','#routes');page='routes'}if(page==='walk'){history.replaceState(null,'','#route/'+id);page='route'}nav(page==='route'?'routes':page==='place'?previousPage:page);if(['explore','saved','map','routes'].includes(page)){previousPage=page;activeWalk=null}if(page==='route')activeWalk=id;if(page==='routes')activeWalk=null;if(page==='explore')renderExplore();else if(page==='place')renderPlace(byId(id));else if(page==='routes')renderWalks();else if(page==='route')renderWalk(WALKS.find(w=>w.id===id));else if(page==='saved')renderSaved();else if(page==='map')renderMap();else renderNotFound();window.scrollTo(0,0);setLiveButtons();window.dispatchEvent(new Event('cityside:render'))}
let watchId=null,lastRefreshPoint=null,arrived=new Set(),liveErrorShown=false;
function setLiveButtons(){const on=watchId!==null;document.querySelectorAll('[data-action="near"]').forEach(b=>{b.classList.toggle('live',on);b.setAttribute('aria-pressed',on);b.innerHTML=icon('location')+(on?(locationPoint?'Live location on':'Locating…'):'Near me')})}
function startLive(){if(!navigator.geolocation){toast('Location is unavailable in this browser. You can still browse the map.');return}if(watchId!==null)return;liveErrorShown=false;watchId=navigator.geolocation.watchPosition(onFix,onFixError,{enableHighAccuracy:true,maximumAge:15000,timeout:20000});putStore('lookup-live',true);setLiveButtons()}
function stopLive(){if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;locationPoint=null;lastRefreshPoint=null;putStore('lookup-live',false);setLiveButtons();refreshLive(true);document.getElementById('arrival')?.remove()}
function onFix(pos){const first=!locationPoint;locationPoint={lat:pos.coords.latitude,lng:pos.coords.longitude};if(first){setLiveButtons();toast('Live location on. Places sort nearest first as you walk. Your location stays on this device.')}
 // Redraw only after moving about 25 meters, so lists don't jump around.
 if(first||LookUpRoutes.miles(lastRefreshPoint,locationPoint)>0.015){lastRefreshPoint=locationPoint;refreshLive(first)}checkArrival()}
function onFixError(err){if(err.code===1){stopLive();toast('Location was not shared. All places and routes are still available.');return}if(!locationPoint&&!liveErrorShown){liveErrorShown=true;toast('Still looking for your location. Try stepping outdoors.')}}
function refreshLive(redraw){const [page]=(location.hash.slice(1)||'explore').split('/');
 document.querySelectorAll('[data-distance]').forEach(el=>{const p=byId(el.dataset.distance);if(p)el.textContent=distanceLabel(p,el.hasAttribute('data-long'))});
 document.querySelectorAll('.place-distance,.route-start').forEach(el=>el.hidden=!locationPoint);
 if(page==='explore'){renderResults();const slot=document.getElementById('hero-slot'),n=nearestPlace();if(slot&&slot.firstElementChild?.dataset.hero!==(n?n.id:''))slot.innerHTML=heroImage()}
 else if(page==='routes')renderRouteResults();
 else if(page==='map'){if(redraw||!userMarker){render()}else{userMarker.setLatLng([locationPoint.lat,locationPoint.lng]);const l=document.getElementById('map-list');if(l)l.innerHTML=mapList()}}}
// About 50 meters: close enough to say "you're here" given phone GPS accuracy.
function checkArrival(){const p=nearestPlace();if(!p||distance(p)>0.03||arrived.has(p.id))return;arrived.add(p.id);
 const w=WALKS.find(w=>w.id===activeWalk&&w.stops.includes(p.id));let checked=false;
 if(w&&!(progress[w.id]||[]).includes(p.id)){progress[w.id]=[...(progress[w.id]||[]),p.id];putStore('cityside-progress',progress);checked=true;if(location.hash==='#route/'+w.id){const y=window.scrollY;render();window.scrollTo(0,y)}}
 document.getElementById('arrival')?.remove();const el=document.createElement('div');el.id='arrival';el.className='arrival';el.setAttribute('role','status');
 el.innerHTML=`<img src="assets/${p.id}.webp" alt=""><div class="arrival-copy"><span class="eyebrow">YOU’RE HERE${checked?' · CHECKED OFF':''}</span><strong>${esc(p.name)}</strong><span class="arrival-actions"><a href="#place/${p.id}">Read the story</a><button data-audio="tour-listen" data-place="${p.id}">Listen</button></span></div><button class="arrival-close" aria-label="Dismiss">×</button>`;
 el.querySelector('.arrival-close').onclick=()=>el.remove();el.querySelector('a').addEventListener('click',()=>el.remove());document.body.appendChild(el);if(navigator.vibrate)navigator.vibrate(80)}
// Pick live location back up if the person turned it on before and already allowed it.
if(readStore('lookup-live',false)===true&&navigator.permissions?.query)navigator.permissions.query({name:'geolocation'}).then(r=>{if(r.state==='granted')startLive()}).catch(()=>{});
main.addEventListener('change',e=>{const key=e.target.dataset.routeFilter;if(!key)return;routeFilters[key]=e.target.value;if(key==='sort'&&e.target.value==='nearest'&&!locationPoint)startLive();renderRouteResults()});
main.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='save'){e.preventDefault();const p=byId(id);if(!p)return;if(saved.has(id))saved.delete(id);else saved.add(id);putStore('cityside-saved',[...saved]);const [page,placeId]=(location.hash.slice(1)||'explore').split('/');if(page==='saved')renderSaved();else{document.querySelectorAll(`[data-action="save"][data-id="${id}"]`).forEach(el=>{el.setAttribute('aria-pressed',saved.has(id));if(el.classList.contains('save-button')){el.classList.toggle('saved',saved.has(id));el.setAttribute('aria-label',`${saved.has(id)?'Unsave':'Save'} ${p.name}`)}else el.innerHTML=icon('bookmark')+(saved.has(id)?'Saved':'Save')})}toast(saved.has(id)?`${p.name} saved for later.`:'Removed from saved places.')}else if(a==='mode'){mode=b.dataset.mode;putStore('cityside-mode',mode);renderExplore()}else if(a==='filter'){filter=b.dataset.filter;document.querySelectorAll('[data-action="filter"]').forEach(el=>{el.classList.toggle('active',el.dataset.filter===filter);el.setAttribute('aria-pressed',el.dataset.filter===filter)});renderResults()}else if(a==='reset-filters'){filter='All places';query='';renderExplore()}else if(a==='near'){if(watchId!==null)stopLive();else startLive()}else if(a==='clear-route-filters'){routeFilters={length:'any',time:'any',region:'All',theme:'All',sort:'recommended'};renderWalks()}else if(a==='visited'){const w=WALKS.find(w=>w.id===b.dataset.walk),scroll=window.scrollY;if(!w||!w.stops.includes(id))return;const d=progress[w.id]||[];progress[w.id]=d.includes(id)?d.filter(x=>x!==id):[...d,id];putStore('cityside-progress',progress);if(mapInstance){mapInstance.remove();mapInstance=null}renderWalk(w);window.scrollTo(0,scroll);toast(progress[w.id].length===w.stops.length?'Walk complete. You know a little more New York.':'Walking progress updated.')}else if(a==='reset-walk'){progress[id]=[];putStore('cityside-progress',progress);if(mapInstance){mapInstance.remove();mapInstance=null}renderWalk(WALKS.find(w=>w.id===id));toast('Ready for another walk.')}else if(a==='start-walk'){const w=WALKS.find(w=>w.id===id),next=w.stops.find(x=>!progress[id].includes(x));if(!next){toast('You’ve finished this walk. Reset progress below to walk it again.');document.getElementById('walk-progress').scrollIntoView({behavior:'smooth'});return}document.getElementById('stop-'+next).scrollIntoView({behavior:'smooth',block:'center'});toast('Start with '+byId(next).name+'. Open directions when you’re ready.')}});
const dialog=document.getElementById('about-dialog');function showAbout(){document.getElementById('all-credits').innerHTML=PLACES.map(p=>`<div class="credit-row"><strong>${p.name}</strong>${credit(p)}</div>`).join('');dialog.showModal()}document.getElementById('about-button').onclick=showAbout;document.getElementById('footer-about').onclick=showAbout;dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();main.focus({preventScroll:false})});
window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true})});
